-- PawSpace UAT DEMO SEED (generated by scripts/uat-demo-seed-gen.mjs — do not hand-edit).
-- Puts real, derivable demo data behind every module UI so no staging page opens empty.
-- Every CREATE TABLE below is copied verbatim from the source file that owns it.
-- All rows are namespaced UATD-* and inserted with INSERT OR IGNORE: safe to re-run,
-- and it never collides with staging-seed.sql or employee-seed.sql.
-- Demo 'today' is 2026-08-13.

CREATE TABLE IF NOT EXISTS ai_conversation_turns (id TEXT PRIMARY KEY,session_id TEXT NOT NULL,thread_id TEXT NOT NULL,customer_id TEXT NOT NULL,input_message_id TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,channel TEXT NOT NULL,intent_code TEXT NOT NULL,intent_confidence REAL NOT NULL,context_id TEXT NOT NULL,provider TEXT NOT NULL,model_ref TEXT,output_text TEXT NOT NULL,latency_ms INTEGER NOT NULL DEFAULT 0,input_tokens INTEGER,output_tokens INTEGER,cost_minor INTEGER,policy_decision TEXT NOT NULL,outcome TEXT NOT NULL,handoff_reason TEXT,created_at INTEGER NOT NULL,completed_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_handoffs (id TEXT PRIMARY KEY,thread_id TEXT NOT NULL,customer_id TEXT NOT NULL,session_id TEXT,reason TEXT NOT NULL,confidence REAL,queue_code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',summary_json TEXT NOT NULL,requested_by TEXT NOT NULL,taken_over_by TEXT,resumed_by TEXT,created_at INTEGER NOT NULL,taken_over_at INTEGER,resumed_at INTEGER);
CREATE TABLE IF NOT EXISTS ai_voice_calls (id TEXT PRIMARY KEY,thread_id TEXT NOT NULL,customer_id TEXT NOT NULL,transport_provider TEXT NOT NULL,direction TEXT NOT NULL,status TEXT NOT NULL,consent_status TEXT NOT NULL,language TEXT,started_at INTEGER NOT NULL,ended_at INTEGER,outcome TEXT,disposition TEXT,live_agent_transfer INTEGER NOT NULL DEFAULT 0,reconnect_count INTEGER NOT NULL DEFAULT 0,created_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_installs (install_id TEXT PRIMARY KEY,source TEXT,campaign TEXT,os TEXT,app_version TEXT,first_open_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS app_users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role_code TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attendance_days (id TEXT PRIMARY KEY,employee_id TEXT NOT NULL,work_date TEXT NOT NULL,status TEXT NOT NULL,first_check_in INTEGER,last_check_out INTEGER,worked_minutes INTEGER,exception_code TEXT,source_policy_id TEXT,updated_at INTEGER NOT NULL,UNIQUE(employee_id,work_date));
CREATE TABLE IF NOT EXISTS boarding_host_profiles (provider_id TEXT PRIMARY KEY,city_id TEXT NOT NULL,zone_id TEXT NOT NULL,area TEXT NOT NULL,species_json TEXT NOT NULL,max_guest_pets INTEGER NOT NULL,one_family_only INTEGER NOT NULL DEFAULT 0,medication_support INTEGER NOT NULL DEFAULT 0,resident_pets TEXT NOT NULL DEFAULT 'none',home_verified INTEGER NOT NULL DEFAULT 0,kyc_status TEXT NOT NULL DEFAULT 'pending',background_check_status TEXT NOT NULL DEFAULT 'pending',active INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,updated_by TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS boarding_stays (id TEXT PRIMARY KEY,booking_id TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL,host_provider_id TEXT NOT NULL,city_id TEXT NOT NULL,zone_id TEXT NOT NULL,package_code TEXT NOT NULL,check_in_at TEXT NOT NULL,check_out_at TEXT NOT NULL,billed_units INTEGER NOT NULL,pet_count INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'awaiting_host_acceptance',care_plan_status TEXT NOT NULL DEFAULT 'required',check_in_status TEXT NOT NULL DEFAULT 'pending',check_out_status TEXT NOT NULL DEFAULT 'pending',extension_status TEXT NOT NULL DEFAULT 'none',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS booking_payments (id TEXT PRIMARY KEY,booking_id TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL,amount REAL NOT NULL,amount_due_now REAL NOT NULL,currency TEXT NOT NULL DEFAULT 'INR',method TEXT NOT NULL,mode TEXT NOT NULL,status TEXT NOT NULL,gateway TEXT NOT NULL DEFAULT 'uat_sandbox',idempotency_key TEXT NOT NULL UNIQUE,detail_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS booking_ratings (id TEXT PRIMARY KEY,booking_id TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL,provider_id TEXT NOT NULL,service_code TEXT NOT NULL,stars INTEGER NOT NULL,comment TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS canonical_bookings (id TEXT PRIMARY KEY,idempotency_key TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL,pet_ids_json TEXT NOT NULL,source_pet_ids_json TEXT NOT NULL,city_id TEXT NOT NULL,zone_id TEXT NOT NULL,service_code TEXT NOT NULL,package_code TEXT NOT NULL,package_name TEXT NOT NULL,schedule_group_id TEXT NOT NULL UNIQUE,provider_id TEXT NOT NULL,scheduled_start TEXT NOT NULL,scheduled_end TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',channel TEXT NOT NULL DEFAULT 'customer_app',total_amount REAL NOT NULL,currency TEXT NOT NULL DEFAULT 'INR',pricing_json TEXT NOT NULL DEFAULT '{}',created_by TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS canonical_customers (id TEXT PRIMARY KEY,city_id TEXT NOT NULL,name TEXT NOT NULL,primary_phone TEXT NOT NULL,secondary_phone TEXT,email TEXT,source TEXT NOT NULL DEFAULT 'uat_customer_app',consent_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS canonical_pets (id TEXT PRIMARY KEY,customer_id TEXT NOT NULL,name TEXT NOT NULL,species TEXT NOT NULL,breed TEXT,vaccination_status TEXT NOT NULL DEFAULT 'not_provided',source_pet_id TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS communication_threads (id TEXT PRIMARY KEY,customer_id TEXT NOT NULL,booking_id TEXT,lead_id TEXT,ticket_id TEXT,status TEXT NOT NULL DEFAULT 'open',assigned_to TEXT,sla_due_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS customer_experience_tickets (id TEXT PRIMARY KEY, customer_id TEXT, booking_id TEXT, lead_id TEXT, category TEXT NOT NULL, priority TEXT NOT NULL, subject TEXT NOT NULL, detail TEXT NOT NULL, owner TEXT NOT NULL, manager TEXT NOT NULL, sla_due_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'open', escalation_level INTEGER NOT NULL DEFAULT 0, customer_status TEXT NOT NULL DEFAULT 'We received your request', resolution TEXT, root_cause TEXT, resolution_evidence TEXT, reopened_count INTEGER NOT NULL DEFAULT 0, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, resolved_at INTEGER);
CREATE TABLE IF NOT EXISTS customer_identity_links (email TEXT PRIMARY KEY, customer_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', verified_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS employee_compensation_assignments (id TEXT PRIMARY KEY,employee_id TEXT NOT NULL,structure_id TEXT NOT NULL,effective_from INTEGER NOT NULL,effective_until INTEGER,reason TEXT NOT NULL,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS employee_employment_versions (id TEXT PRIMARY KEY,employee_id TEXT NOT NULL,version INTEGER NOT NULL,effective_from INTEGER NOT NULL,effective_until INTEGER,employment_type TEXT,probation_status TEXT,title TEXT,team_code TEXT,manager_employee_id TEXT,cost_centre_code TEXT,location_code TEXT,reason TEXT NOT NULL,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(employee_id,version));
CREATE TABLE IF NOT EXISTS employee_incentive_periods (id TEXT PRIMARY KEY,idempotency_key TEXT NOT NULL UNIQUE,scheme_id TEXT NOT NULL,period_start INTEGER NOT NULL,period_end INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'calculated',calculated_by TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS employee_incentive_results (id TEXT PRIMARY KEY,period_id TEXT NOT NULL,employee_id TEXT NOT NULL,employee_email TEXT NOT NULL,source_fact_run_id TEXT NOT NULL,metric_value REAL NOT NULL,calculated_amount REAL NOT NULL,approved_amount REAL NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'calculated',evidence_json TEXT NOT NULL,approved_by TEXT,approved_at INTEGER,UNIQUE(period_id,employee_id));
CREATE TABLE IF NOT EXISTS employee_leave_balances (employee_id TEXT NOT NULL,leave_code TEXT NOT NULL,balance REAL NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL,PRIMARY KEY(employee_id,leave_code));
CREATE TABLE IF NOT EXISTS employee_payroll_results (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,employee_id TEXT NOT NULL,structure_id TEXT NOT NULL,gross_earnings REAL NOT NULL,total_deductions REAL NOT NULL,reimbursements REAL NOT NULL,employer_cost REAL NOT NULL,net_pay REAL NOT NULL,source_snapshot_json TEXT NOT NULL,UNIQUE(run_id,employee_id));
CREATE TABLE IF NOT EXISTS employees (id TEXT PRIMARY KEY,user_email TEXT UNIQUE,employee_code TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,work_email TEXT NOT NULL UNIQUE,phone TEXT,employment_status TEXT NOT NULL DEFAULT 'active',joined_at INTEGER,ended_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS finance_bills (id text PRIMARY KEY NOT NULL,vendor_id text NOT NULL,bill_number text NOT NULL,bill_date text NOT NULL,due_date text NOT NULL,cost_centre text NOT NULL,vertical text NOT NULL,taxable_amount real NOT NULL,gst_amount real NOT NULL,tds_amount real DEFAULT 0 NOT NULL,total_amount real NOT NULL,status text DEFAULT 'draft' NOT NULL,purchase_order_id text,attachment_reference text,created_at integer NOT NULL,updated_at integer NOT NULL);
CREATE TABLE IF NOT EXISTS finance_expenses (id text PRIMARY KEY NOT NULL,expense_date text NOT NULL,claimant text NOT NULL,merchant text NOT NULL,category text NOT NULL,cost_centre text NOT NULL,vertical text NOT NULL,amount real NOT NULL,gst_amount real DEFAULT 0 NOT NULL,payment_mode text NOT NULL,receipt_reference text,status text DEFAULT 'submitted' NOT NULL,duplicate_risk integer DEFAULT 0 NOT NULL,created_at integer NOT NULL,updated_at integer NOT NULL);
CREATE TABLE IF NOT EXISTS finance_journal_entries (id text PRIMARY KEY NOT NULL,entry_date text NOT NULL,source_type text NOT NULL,source_id text NOT NULL,account_code text NOT NULL,cost_centre text,vertical text,debit real DEFAULT 0 NOT NULL,credit real DEFAULT 0 NOT NULL,narration text NOT NULL,period_code text NOT NULL,posted integer DEFAULT 0 NOT NULL,created_at integer NOT NULL);
CREATE TABLE IF NOT EXISTS incentive_scheme_versions (id TEXT PRIMARY KEY,scheme_code TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',role_code TEXT NOT NULL,team_code TEXT NOT NULL,effective_from INTEGER NOT NULL,effective_until INTEGER,formula_json TEXT NOT NULL,quality_rules_json TEXT NOT NULL DEFAULT '[]',approval_reference TEXT,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(scheme_code,version));
CREATE TABLE IF NOT EXISTS install_identity_links (install_id TEXT PRIMARY KEY,customer_id TEXT NOT NULL,identified_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lead_work_items (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL, source TEXT NOT NULL, service TEXT NOT NULL, owner TEXT NOT NULL, manager TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', stage TEXT NOT NULL DEFAULT 'day_1', work_day INTEGER NOT NULL DEFAULT 1, assigned_at INTEGER NOT NULL, first_action_due_at INTEGER NOT NULL, manager_alert_at INTEGER NOT NULL, first_action_at INTEGER, call_attempts INTEGER NOT NULL DEFAULT 0, whatsapp_attempts INTEGER NOT NULL DEFAULT 0, last_outcome TEXT, next_action_at INTEGER, recycle_at INTEGER, recycle_cycle INTEGER NOT NULL DEFAULT 0, opt_out INTEGER NOT NULL DEFAULT 0, converted_booking_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS leave_requests (id TEXT PRIMARY KEY,employee_id TEXT NOT NULL,leave_code TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,units REAL NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',requested_by TEXT NOT NULL,approved_by TEXT,approved_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payroll_approval_events (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,event_type TEXT NOT NULL,actor_id TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payroll_result_lines (id TEXT PRIMARY KEY,result_id TEXT NOT NULL,component_code TEXT NOT NULL,label TEXT NOT NULL,kind TEXT NOT NULL,amount REAL NOT NULL,source_type TEXT NOT NULL,source_reference TEXT,policy_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payroll_runs (id TEXT PRIMARY KEY,idempotency_key TEXT NOT NULL UNIQUE,period_start INTEGER NOT NULL,period_end INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',input_snapshot_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,reviewed_by TEXT,reviewed_at INTEGER,approved_by TEXT,approved_at INTEGER,payment_prepared_at INTEGER);
CREATE TABLE IF NOT EXISTS payslips (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,employee_id TEXT NOT NULL,result_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'available_uat',created_at INTEGER NOT NULL,UNIQUE(run_id,employee_id));
CREATE TABLE IF NOT EXISTS pet_birthdays (pet_id TEXT PRIMARY KEY,customer_id TEXT NOT NULL,date_of_birth TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pet_vaccinations (id TEXT PRIMARY KEY,pet_id TEXT NOT NULL,customer_id TEXT NOT NULL,vaccine_type TEXT NOT NULL,administered_on TEXT NOT NULL,next_due_on TEXT,administered_by TEXT,notes TEXT,status TEXT NOT NULL DEFAULT 'active',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS provider_commercial_terms (id TEXT PRIMARY KEY,service_code TEXT NOT NULL,provider_id TEXT,version INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',engagement_model TEXT NOT NULL,provider_share_pct REAL NOT NULL,gst_mode TEXT NOT NULL,platform_gst_rate REAL NOT NULL DEFAULT 0.18,cash_allowed INTEGER NOT NULL DEFAULT 0,onboarding_fee REAL NOT NULL DEFAULT 0,renewal_fee REAL NOT NULL DEFAULT 0,renewal_months INTEGER NOT NULL DEFAULT 12,effective_from TEXT NOT NULL,reason TEXT NOT NULL,created_by TEXT NOT NULL,approved_by TEXT,approval_reference TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS provider_identity_links (email TEXT PRIMARY KEY, provider_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', verified_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
